  guild_id: input.guild_id,
  user_request: input.user_request
};

const input = $input.first().json;

// Build system prompt with user_request context
const systemPrompt = `Tu es un assistant d'analyse d'intention pour le contexte "${input.context.type}".

**Demande utilisateur originale:** "${input.user_request}"

RÈGLES:
1. Analyse la requête utilisateur ET l'historique de conversation
2. Tiens compte de la demande utilisateur originale ci-dessus pour contextualiser
3. Détermine le response_type approprié
4. Propose des actions avec leur ID (PAS de webhook)
5. Réponds UNIQUEMENT en JSON valide

DÉFINITION DU CONTEXTE "${input.context.type}":
${input.context.type === 'recipe' ? `
Pour "recipe", TOUTES ces questions sont PERTINENTES (is_relevant: true):
- Recettes et préparations
- Techniques culinaires (couper, découper, trancher, émincer, etc.)
- Conseils de cuisson (temps, température, méthode)
- Questions sur les ingrédients
- Astuces cuisine, conservation, équipement

SEULES ces questions sont HORS CONTEXTE (is_relevant: false):
- Questions sans rapport avec la cuisine/alimentation
` : input.context.type === 'torah' ? `
Pour "torah", accepter: traduction, étude, commentaires, recherche textuelle.
` : `
Contexte général: accepter les questions d'information et de recherche.
`}

ACTIONS DISPONIBLES (utilise ces IDs):
- "search" : Recherche web
- "local_search" : Recherche base locale
- "scrape" : Extraire contenu d'une URL
- "info" : Réponse informative simple

FORMAT DE SORTIE JSON:
{
  "response_type": "message" | "action_proposal" | "clarification_needed",
  "message": "Réponse à l'utilisateur",
  "intent": { "type": "...", "confidence": 0.0-1.0 },
  "query_analysis": {
    "original": "requête originale",
    "reformulation": "requête reformulée",
    "extracted_terms": "termes clés en STRING (pas un array)",
    "detected_language": "fr",
    "spelling_corrected": false
  },
  "proposed_actions": [{
    "id": "search",
    "label": "Label affiché",
    "description": "Description de l'action",
    "params": { "query": "termes de recherche" },
    "requires_confirmation": false
  }],
  "is_relevant": true,
  "rejection_reason": null
}

IMPORTANT:
- N'INCLUS JAMAIS de champ "webhook" dans proposed_actions
- extracted_terms DOIT être une STRING, pas un array
- En cas de doute sur la pertinence, mets is_relevant: true`;

// Build messages array with history
const messages = [];

// Add history (already truncated to 10 in validation)
if (input.history && input.history.length > 0) {
  for (const h of input.history) {
    messages.push({ role: h.role, content: h.content });
  }
}

// Add current user message
let userContent = input.message;
if (input.attached_file) {
  const fileName = input.attached_file.name || 'document';
  const fileType = input.attached_file.type || 'unknown';
  userContent = `[Fichier joint: ${fileName} (${fileType})]\n\n${input.message}`;
}
messages.push({ role: 'user', content: userContent });

// Build final payload
const payload = {
  model: input.llm_model,
  max_tokens: 1000,
  system: systemPrompt,
  messages: messages
};

return {
  json: {
    ...input,
    llm_payload: payload
  }
};

// ============================================
// PARSE LLM RESPONSE - LLM Intention
// ============================================

const input = $input.first().json;
const prevData = $('Build LLM Payload').first().json;
const startTime = prevData.startTime || Date.now();

// --- Context fields for traceability ---
const userId = prevData.user_id;
const guildId = prevData.guild_id;
const userRequest = prevData.user_request;

const statusCode = input.statusCode || 200;

// Initialize trace with llm_response format
const _trace = {
  llm_response: null,
  service_response: null,
  provider: 'anthropic',
  model: prevData.llm_model,
  tokens: { input: 0, output: 0 },
  latency_ms: 0,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest
};

// Handle LLM API error
if (statusCode >= 400) {
  const errorMsg = input.body?.error?.message || 'LLM API error';
  _trace.llm_response = `Error: ${errorMsg}`;
  _trace.service_response = input.body || input;
  _trace.latency_ms = Date.now() - startTime;

  return {
    json: {
      success: false,
      error: {
        code: 'LLM_ERROR',
        message: errorMsg,
        http_status: statusCode
      },
      user_id: userId,
      guild_id: guildId,
      user_request: userRequest,
      _trace: _trace
    }
  };
}

// Extract LLM response
const body = input.body || input;
const content = body.content?.[0]?.text || '';
const usage = body.usage || {};

// Populate trace with LLM response
_trace.llm_response = content;
_trace.service_response = body;
_trace.tokens = {
  input: usage.input_tokens || 0,
  output: usage.output_tokens || 0
};

// Parse JSON from LLM response
let analysis;
try {
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    analysis = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No JSON found in response');
  }
} catch (e) {
  // Default analysis if parsing fails
  analysis = {
    response_type: 'message',
    message: content || 'Je n\'ai pas compris votre demande.',
    intent: { type: 'unknown', confidence: 0.5 },
    query_analysis: {
      original: prevData.message,
      reformulation: prevData.message,
      extracted_terms: '',
      detected_language: 'fr',
      spelling_corrected: false
    },
    proposed_actions: [],
    is_relevant: true,
    rejection_reason: null
  };
}

_trace.latency_ms = Date.now() - startTime;

// Ensure RFC-016 format
const result = {
  success: true,
  response_type: analysis.response_type || 'message',
  message: analysis.message || '',
  intent: analysis.intent || { type: 'unknown', confidence: 0 },
  query_analysis: analysis.query_analysis || {
    original: prevData.message,
    reformulation: prevData.message,
    extracted_terms: '',
    detected_language: 'fr',
    spelling_corrected: false
  },
  proposed_actions: analysis.proposed_actions || [],
  is_relevant: analysis.is_relevant !== false,
  rejection_reason: analysis.rejection_reason || null,
  // Pass through for next nodes
  context: prevData.context,
  plugin_context: prevData.plugin_context,
  user: prevData.user,
  message_original: prevData.message,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  startTime: startTime,
  _trace: _trace
};

return { json: result };

// ============================================
// BUILD REJECT RESPONSE
// ============================================

const input = $input.first().json;
const startTime = input.startTime || Date.now();

const _trace = {
  llm_response: input._trace?.llm_response || null,
  service_response: { rejection: true, reason: input.rejection_reason },
  provider: 'anthropic',
  model: input._trace?.model || 'claude-3-haiku-20240307',
  tokens: input._trace?.tokens || { input: 0, output: 0 },
  latency_ms: Date.now() - startTime,
  user_id: input.user_id,
  guild_id: input.guild_id,
  user_request: input.user_request
};

return {
  json: {
    success: true,
    response_type: 'message',
    message: input.rejection_reason || `Cette requête ne concerne pas le contexte ${input.context?.type || 'demandé'}.`,
    intent: {
      type: 'out_of_context',
      confidence: input.intent?.confidence || 0
    },
    query_analysis: input.query_analysis || {
      original: input.message_original,
      reformulation: input.message_original,
      extracted_terms: '',
      detected_language: 'fr',
      spelling_corrected: false
    },
    proposed_actions: [],
    is_relevant: false,
    rejection_reason: input.rejection_reason,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request,
    _trace: _trace
  }
};

