// ============================================
// BUILD FINAL RESPONSE - LLM Intention
// ============================================

const qdrantResponse = $input.first().json;
const prevData = $('Parse LLM Response').first().json;
const startTime = prevData.startTime || Date.now();

// --- Context fields for traceability ---
const userId = prevData.user_id;
const guildId = prevData.guild_id;
const userRequest = prevData.user_request;

// Webhooks: utilise ceux du context si fournis, sinon defaults
const webhooks = prevData.context?.webhooks || {
  search: '/webhook/llm-web-search',
  scrape: '/webhook/web-scraper',
  local_search: '/webhook/qdrant-search'
};

// NOUVEAU: Si pas relevant, ne pas proposer d'actions
if (!prevData.is_relevant) {
  const _trace = {
    llm_response: prevData._trace?.llm_response || null,
    service_response: { qdrant_skipped: true, reason: 'not_relevant' },
    provider: 'anthropic',
    model: prevData._trace?.model || 'claude-3-haiku-20240307',
    tokens: prevData._trace?.tokens || { input: 0, output: 0 },
    latency_ms: Date.now() - startTime,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };

  return {
    json: {
      success: true,
      response_type: 'message',
      message: prevData.message || 'Requête hors contexte.',
      intent: prevData.intent,
      query_analysis: prevData.query_analysis,
      proposed_actions: [],
      is_relevant: false,
      rejection_reason: prevData.rejection_reason,
      user_id: userId,
      guild_id: guildId,
      user_request: userRequest,
      _trace: _trace
    }
  };
}

// Extract Qdrant results
const qdrantBody = qdrantResponse.body || qdrantResponse;
const qdrantSuccess = qdrantBody.success !== false;
const qdrantResults = qdrantBody.data?.results || [];

// Find best score
let bestScore = 0;
if (qdrantResults.length > 0) {
  bestScore = Math.max(...qdrantResults.map(r => r.score || 0));
}

// Check against threshold
const minScore = prevData.context?.min_score || 0.7;
const aboveThreshold = bestScore >= minScore;

// Start with LLM analysis
let responseType = prevData.response_type || 'message';
let message = prevData.message || '';

// Nettoyer les proposed_actions du LLM (supprimer les webhooks inventés)
let proposedActions = (prevData.proposed_actions || []).map(action => ({
  ...action,
  webhook: null  // On ne fait pas confiance aux webhooks du LLM
}));

// Enrich proposed_actions based on Qdrant results
if (qdrantResults.length > 0 && aboveThreshold) {
  // Good results found - add them to context
  responseType = 'action_proposal';
  message = message || `J'ai trouvé ${qdrantResults.length} résultat(s) pertinent(s).`;

  // Add search results action if not already present
  const hasSearchAction = proposedActions.some(a => a.id === 'return_results');
  if (!hasSearchAction) {
    proposedActions.unshift({
      id: 'return_results',
      label: 'Voir les résultats',
      description: `${qdrantResults.length} résultat(s) trouvé(s) (score: ${Math.round(bestScore * 100)}%)`,
      webhook: null,
      params: { results: qdrantResults },
      requires_confirmation: false,
      estimate: null
    });
  }
} else if (qdrantResults.length === 0 || !aboveThreshold) {
  // No good results - propose web search if relevant
  const hasWebSearch = proposedActions.some(a => a.id === 'web_search' || a.id === 'search');
  if (!hasWebSearch && prevData.is_relevant) {
    const autoFallback = prevData.context?.auto_fallback === true;
    responseType = 'action_proposal';
    const reason = qdrantResults.length === 0
      ? 'Aucun résultat trouvé dans la base locale.'
      : `Résultats peu pertinents (score: ${Math.round(bestScore * 100)}%).`;

    if (autoFallback) {
      message = message || `${reason} Recherche web en cours...`;
    } else {
      message = message || `${reason} Voulez-vous chercher sur le web ?`;
    }

    proposedActions.push({
      id: 'search',
      label: 'Rechercher sur le web',
      description: 'Lancer une recherche web pour trouver des résultats',
      webhook: webhooks.search,
      params: {
        query: Array.isArray(prevData.query_analysis?.extracted_terms)
          ? prevData.query_analysis.extracted_terms.join(' ')
          : (prevData.query_analysis?.extracted_terms || prevData.message_original)
      },
      requires_confirmation: !autoFallback,
      estimate: { credits: 1, unit: 'search', quantity: 1 }
    });
  }
}

// Build _trace for Langfuse observability
const _trace = {
  llm_response: prevData._trace?.llm_response || null,
  service_response: {
    qdrant: {
      searched: true,
      result_count: qdrantResults.length,
      best_score: bestScore,
      above_threshold: aboveThreshold
    }
  },
  provider: 'anthropic',
  model: prevData._trace?.model || 'claude-3-haiku-20240307',
  tokens: prevData._trace?.tokens || { input: 0, output: 0 },
  latency_ms: Date.now() - startTime,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest
};

return {
  json: {
    success: true,
    response_type: responseType,
    message: message,
    intent: prevData.intent,
    query_analysis: prevData.query_analysis,
    proposed_actions: proposedActions,
    is_relevant: prevData.is_relevant,
    rejection_reason: null,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest,
    _qdrant: {
      searched: true,
      result_count: qdrantResults.length,
      best_score: bestScore,
      above_threshold: aboveThreshold
    },
    _trace: _trace
  }
};
